<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\User;
class AuthTest extends TestCase{use RefreshDatabase;public function test_customer_can_register():void{$r=$this->post('/register',['name'=>'Test','email'=>'test@example.com','password'=>'password123','password_confirmation'=>'password123']);$r->assertRedirect('/dashboard');$this->assertAuthenticated();$this->assertDatabaseHas('users',['email'=>'test@example.com','role'=>'customer']);}public function test_customer_can_login():void{$u=User::create(['name'=>'Test','email'=>'test@example.com','password'=>'password123','role'=>'customer']);$this->post('/login',['email'=>$u->email,'password'=>'password123'])->assertRedirect('/dashboard');$this->assertAuthenticatedAs($u);}}
